import React from 'react';
import'./Signup.css';

function Signup() {
  return (
    <div className="signupContainer">
      <form className="signupForm montserratFont">
        <h2>Sign Up</h2>
        <input autoCapitalize="none" autofille="off" autoCorrect="off" className="textField"  type="text" placeholder="User Name" />
        <input autoCapitalize="none" autoComplete="off" autoCorrect="off" className="textField" type="email" placeholder="Email" />
        <input autoCapitalize="none" autoComplete="off" autoCorrect="off" className="textField" type="password" placeholder="Password" />
        <button className="signupButton" type="submit">Sign Up</button>
      </form>
      <p>
        Already have an account? <a href="/signin">Sign In</a>
      </p>
    </div>
  );
}

export default Signup;
